// ╨У╨╛╤В╨╛╨▓╨╕╨╝ shell-╨║╨╛╨╝╨░╨╜╨┤╤Г ╨╜╨░ ╤Е╨╛╤Б╤В ╤Б yt-dlp/ffmpeg (╤В╨╛╤В ╨╢╨╡ SSH-╨║╤А╨╡╨┤, ╤З╤В╨╛ ╤Г
// ┬л╨б╨║╨░╤З╨╕╨▓╨░╨╡╨╝ ╨░╤Г╨┤╨╕╨╛┬╗ ╨▓ ZOOM-╤Б╤Ж╨╡╨╜╨░╤А╨╕╨╕). ╨б╨╛╨▒╨╕╤А╨░╨╡╨╝ ╤Б╤В╤А╨╛╨║╤Г ╨╖╨┤╨╡╤Б╤М, ╨░ ╨╜╨╡ ╨▓ SSH-╨╜╨╛╨┤╨╡:
// ╨▓ JS ╤Н╨║╤А╨░╨╜╨╕╤А╨╛╨▓╨░╨╜╨╕╨╡ ╨║╨░╨▓╤Л╤З╨╡╨║ ╤З╨╕╤В╨░╨╡╨╝╨╛ ╨╕ ╨┐╤А╨╛╨▓╨╡╤А╤П╨╡╨╝╨╛.
//
// ╨б╨╡╨║╤А╨╡╤В╤Л VK тАФ ╨Э╨Х ╨▓ n8n: ╨┤╨╛╤Б╤В╤Г╨┐ Code-╨╜╨╛╨┤ ╨║ $env ╨▓ ╤Н╤В╨╛╨╣ ╨╕╨╜╤Б╤В╨░╨╗╨╗╤П╤Ж╨╕╨╕ ╨╖╨░╨║╤А╤Л╤В
// (N8N_BLOCK_ENV_ACCESS_IN_NODE тЖТ ┬лaccess to env vars denied┬╗, 29.07.2026).
// ╨в╨╛╨║╨╡╨╜ ╨╕ id ╨│╤А╤Г╨┐╨┐╤Л ╨╢╨╕╨▓╤Г╤В ╨▓ /root/.clip-env ╨╜╨░ ffmpeg-╤Е╨╛╤Б╤В╨╡, ╨║╨╛╨╝╨░╨╜╨┤╨░ ╤Б╨░╨╝╨░ ╨╕╤Е
// ╨┐╨╛╨┤╤Е╨▓╨░╤В╤Л╨▓╨░╨╡╤В. ╨Т git ╨╕ ╨▓ ╤Н╤В╨╛╨╝ ╤Д╨░╨╣╨╗╨╡ ╨╕╤Е ╨╜╨╡╤В.

// ╨Ю╨┤╨╕╨╜╨░╤А╨╜╤Л╨╡ ╨║╨░╨▓╤Л╤З╨║╨╕ ╨▓ bash: ╨╖╨░╨║╤А╤Л╤В╤М, ╨▓╤Б╤В╨░╨▓╨╕╤В╤М ╤Н╨║╤А╨░╨╜╨╕╤А╨╛╨▓╨░╨╜╨╜╤Г╤О, ╨╛╤В╨║╤А╤Л╤В╤М ╨╖╨░╨╜╨╛╨▓╨╛.
const sh = (v) => "'" + String(v).replace(/'/g, "'\\''") + "'";

return $input.all().map((item) => {
  const j = item.json;
  const src = '/data/clips/src-' + j.lesson_id + '.mp4';
  const out = '/data/clips/lesson-' + j.lesson_id + '-' + j.index + '.mp4';
  const title = String(j.title).slice(0, 120);

  const command = [
    'set -eu',
    '[ -r /root/.clip-env ] || { echo "╨╜╨╡╤В /root/.clip-env (╨╜╤Г╨╢╨╜╤Л VK_ACCESS_TOKEN ╨╕ VK_VIDEO_GROUP_ID)" >&2; exit 1; }',
    '. /root/.clip-env',
    ': "${VK_ACCESS_TOKEN:?╨┐╤Г╤Б╤В ╨▓ /root/.clip-env}"',
    ': "${VK_VIDEO_GROUP_ID:?╨┐╤Г╤Б╤В ╨▓ /root/.clip-env}"',
    'mkdir -p /data/clips',
    // ╨Ш╤Б╤Е╨╛╨┤╨╜╨╕╨║ ╤В╤П╨╜╨╡╨╝ ╨╛╨┤╨╕╨╜ ╤А╨░╨╖ ╨╜╨░ ╨▓╤Б╤О ╨╗╨╡╨║╤Ж╨╕╤О: ╤Б╨┐╨░╨╜╨╛╨▓ ╨┤╨╛ 5, ╨║╨░╤З╨░╤В╤М ╨╕╤Е ╨┐╨╛ ╨╛╤В╨┤╨╡╨╗╤М╨╜╨╛╤Б╤В╨╕
    // ╨╖╨╜╨░╤З╨╕╨╗╨╛ ╨▒╤Л 5 ╨┐╨╛╨╗╨╜╤Л╤Е ╨╖╨░╨│╤А╤Г╨╖╨╛╨║ ╨┐╨╛╨╗╤Г╤В╨╛╤А╨░╤З╨░╤Б╨╛╨▓╨╛╨│╨╛ ╨▓╨╕╨┤╨╡╨╛.
    '[ -s ' + sh(src) + ' ] || yt-dlp --extractor-args "youtube:oauth2" --extractor-args "youtube:player_client=android,web" -f "bv*+ba/b" --merge-output-format mp4 --no-warnings -o ' + sh(src) + ' ' + sh(j.video_url),
    // -c copy: ╨▒╨╡╨╖ ╨┐╨╡╤А╨╡╨║╨╛╨┤╨╕╤А╨╛╨▓╨░╨╜╨╕╤П, ╤А╨╡╨╢╨╡╨╝ ╨┐╨╛ ╨║╨╗╤О╤З╨╡╨▓╤Л╨╝ ╨║╨░╨┤╤А╨░╨╝ тАФ ╤Б╨╡╨║╤Г╨╜╨┤╤Л, ╨╜╨╡ ╨╝╨╕╨╜╤Г╤В╤Л.
    'ffmpeg -y -hide_banner -loglevel error -ss ' + Number(j.start_seconds) + ' -to ' + Number(j.end_seconds) + ' -i ' + sh(src) + ' -c copy ' + sh(out),
    // video.save ╨╛╤В╨┤╨░╤С╤В upload_url ╨╕ ╤Г╨╢╨╡ ╨│╨╛╤В╨╛╨▓╤Л╨╡ owner_id/video_id.
    'SAVE=$(curl -s -G "https://api.vk.com/method/video.save" --data-urlencode ' + sh('name=' + title) + ' --data-urlencode "group_id=$VK_VIDEO_GROUP_ID" --data-urlencode "\1***REDACTED***SS_TOKEN" --data-urlencode "v=5.131")',
    'printf %s "$SAVE" | grep -q upload_url || { printf %s "$SAVE" >&2; exit 1; }',
    'UP=$(printf %s "$SAVE" | python3 -c "import sys,json;print(json.load(sys.stdin)[\'response\'][\'upload_url\'])")',
    'curl -s -F ' + sh('video_file=@' + out) + ' "$UP" > /dev/null',
    'rm -f ' + sh(out),
    'printf %s "$SAVE" | python3 -c "import sys,json;r=json.load(sys.stdin)[\'response\'];print(json.dumps({\'vk_video_id\':r[\'video_id\'],\'vk_owner_id\':r[\'owner_id\']}))"',
  ].join('\n');

  return { json: { ...j, command } };
});

// SSH-╨╜╨╛╨┤╨░ ╨║╨╗╨░╨┤╤С╤В ╨▓╤Л╨▓╨╛╨┤ ╨▓ stdout. ╨Я╨╛╤Б╨╗╨╡╨┤╨╜╤П╤П ╤Б╤В╤А╨╛╨║╨░ тАФ JSON ╤Б id ╤А╨╛╨╗╨╕╨║╨░.
return $input.all().map((item) => {
  const raw = String(item.json.stdout ?? '').trim();
  const last = raw.split('\n').filter(Boolean).pop() ?? '';
  let parsed = {};
  try {
