  }
  return { json: parsed };
});

// ╨б╨╛╨▒╨╕╤А╨░╨╡╨╝ ╨╛╨┤╨╕╨╜ callback ╨╜╨░ ╨▓╤Б╤О ╨╗╨╡╨║╤Ж╨╕╤О. ╨Я╨╛╨╗╤П ╤Б╨┐╨░╨╜╨░ ╨▒╨╡╤А╤С╨╝ ╨╕╨╖ ┬лExpand spans┬╗
// ╨┐╨╛ ╨╕╨╜╨┤╨╡╨║╤Б╤Г: ╤Ж╨╡╨┐╨╛╤З╨║╨░ ╨╗╨╕╨╜╨╡╨╣╨╜╨░╤П ╨╕ 1:1, ╨┐╨╛╤А╤П╨┤╨╛╨║ ╤Б╨╛╤Е╤А╨░╨╜╤П╨╡╤В╤Б╤П, ╨░ $json ╨║ ╤Н╤В╨╛╨╝╤Г
// ╨╝╨╛╨╝╨╡╨╜╤В╤Г ╤Б╨╛╨┤╨╡╤А╨╢╨╕╤В ╤В╨╛╨╗╤М╨║╨╛ ╨╛╤В╨▓╨╡╤В VK.
const vkItems = $input.all();
const spans = $('Expand spans').all();
const clips = vkItems.map((it, i) => {
